            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if agent_id == 'Cindy':
                    cindy_bid = bid
                else:
                    strong_non_cindy.append(bid)

    if not alive:
        return min(budget, 20.0)

    alive_count = len(alive)
    units = supply / float(WATER_REQ)
    scarcity = units / float(alive_count + 1)

    max_prev = max(prev_bids) if prev_bids else 0.0
    ref_non_cindy = max(strong_non_cindy) if strong_non_cindy else 0.0

    if hp <= 2 or no_water_days >= 2:
        emergency = max(92.0, ref_non_cindy + 8.0)
        if cindy_bid is not None and cindy_bid < emergency and hp <= 1:
            emergency = cindy_bid + 3.0
        return min(budget, emergency)

    if hp <= 4 or no_water_days >= 1:
        urgent = max(78.0, ref_non_cindy + 4.0)
        if scarcity < 0.45:
            urgent += 8.0
        return min(budget, urgent)

    if scarcity >= 0.7:
        bid = 36.0
    elif scarcity >= 0.5:
        bid = max(48.0, ref_non_cindy - 6.0)
    else:
        bid = max(68.0, ref_non_cindy + 2.5)

    if cindy_bid is not None and cindy_bid > 95.0 and hp >= 5:
        bid = min(bid, 74.0)

    if day >= 8 and hp >= 6:
        bid = min(bid, 58.0)

    if budget < DAILY_SALARY * 2:
        bid = min(bid, max(28.0, budget * 0.55))

    return min(budget, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', None) or {}
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are likely needed today.
    # With simultaneous auctions, bid more when supply is tight.
    # supply in [15,25] implies 1 or 2 units of water requirement.
    # Use a conservative target: if supply is closer to 15, assume only 1 unit.
    if supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        # tighter day
        pressure = 1.0
    else:
        pressure = 0.7

    # If my hp is low or I've already gone without water, increase bid.
    if hp <= 2.0 or no_water_days >= 2:
        self_need = 1.0
    elif hp <= 4.0 or no_water_days == 1:
        self_need = 0.75
    else:
        self_need = 0.55

    # Opponent aggression signal: if someone bid near/above salary, they likely fight for water.
    if highest_prev_bid >= DAILY_SALARY * 0.95:
        opp_aggression = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.7:
        opp_aggression = 0.85
    elif highest_prev_bid >= DAILY_SALARY * 0.5:
        opp_aggression = 0.7
    else:
        opp_aggression = 0.55

    # Base bid: aim to be competitive but not maximal.
    # Target roughly around 0.55-0.85 of salary, scaled by pressure and needs.
    target = DAILY_SALARY * 0.55
    target *= (0.65 + 0.35 * pressure)
    target *= (0.6 + 0.4 * self_need)
    target *= (0.6 + 0.4 * opp_aggression)

    # If opponents were bidding high yesterday, nudge upward slightly.
    if highest_prev_bid > 0.0:
        # Keep within a reasonable band; avoid matching their max exactly.
        target = max(target, min(DAILY_SALARY * 0.85, highest_prev_bid * 0.75 + 5.0))

    # Ensure we don't bid above budget.
    bid = max(0.0, min(budget, target))

    # If budget is very low, still bid enough to try once.
    if budget <= DAILY_SALARY * 0.2:
        bid = max(0.0, min(budget, DAILY_SALARY * 0.15))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    avg_prev_bid = sum(prev_bids) / len(prev_bids)
    max_prev_bid = max(prev_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev_bid * 1.1 + 5)

    if supply < WATER_REQ * 1.5:
        return min(my_status['budget'], avg_prev_bid * 0.8)

    return min(my_status['budget'], max(DAILY_SALARY * 0.5, avg_prev_bid * 1.05))
